head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _1 : GroupBy 를 적용해 "화면 표시 Row 순서 != DataList 데이터 Row 순서" 상태를 만들고
//     - 데이터 Row 의 표시 인덱스 -> getRealRowIndex -> DataList 인덱스(Number) 반환
//     - GroupBy Header/Footer Row 의 표시 인덱스 -> Group 정보(Object) 반환 (.type = header/footer)
//     - 유효하지 않은 파라미터(음수/범위초과) / 파라미터 생략 -> undefined 반환
//   · par_rowIndex(표시 인덱스) select 에서 값을 고르고 getRealRowIndex 버튼을 클릭하면 호출된다.
//     "생략" 옵션 선택 후 버튼 클릭 시 인자 없이 target1.getRealRowIndex() 를 호출한다.
scwin.tData = {
    "description" : "[gridView > M > getRealRowIndex]<br/>GridView 에 표시된 Row 기준의 인덱스를 DataList 기준의 인덱스로 반환합니다.",
    "validation" : [
        "DrillDown, GroupBy 등이 적용되었을때 화면에 보이는 Row 순서와 DataList 의 데이터 Row 순서는 다를 수 있습니다.",
        "rowIndex(선택) 파라미터로 변환하려는 GridView 표시 기준 인덱스를 설정합니다.",
        "rowIndex(선택) 파라미터의 Row 인덱스는 0 부터 시작하며 GridView 에 표시된 Row 기준으로 인덱스를 설정합니다.",
        "DataList 의 데이터 Row 기준 인덱스를 반환합니다.",
        "GroupBy 가 적용되었을때 Header/Footer Row 인덱스를 파라미터로 설정 시 Group 정보가 Object 로 반환됩니다.",
        "유효하지 않은 파라미터 설정 시 undefined 값이 반환됩니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - region 컬럼(인덱스 0) 기준 GroupBy 를 comp_init 에서 바로 적용 → 로드 시점부터 그룹화 상태
//  - GroupBy 로 인해 화면 표시 순서가 DataList 순서와 달라지고, 그룹마다 Header/Footer Row 가 삽입됨
//  - ★ GroupBy 는 바인딩 DataList 를 물리적으로 정렬한다. getRealRowIndex 는 원본(정렬 전) 인덱스를 반환하므로
//    dlt_bind.getCellData(real) 로 표시행과 대조하려면 DataList 를 미리 그룹 정렬 순서(region 오름차순)로 넣어
//    원본 인덱스와 물리 인덱스가 같도록 구성한다. (표시≠데이터는 그룹 Header/Footer Row 삽입으로 여전히 성립)
//  - 표시 레이아웃(표시 인덱스 → 내용):
//      0: [부산 그룹 Header]   (Object)
//      1: 부산/김철수  → DataList idx 0 (Number)
//      2: 부산/박민수  → DataList idx 1 (Number)
//      3: [부산 그룹 Footer]   (Object)
//      4: [서울 그룹 Header]   (Object)
//      5: 서울/홍길동  → DataList idx 2 (Number)
//      6: 서울/이영희  → DataList idx 3 (Number)
//      7: [서울 그룹 Footer]   (Object)
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] region(지역) 컬럼 기준 GroupBy 적용 그리드. GroupBy 로 그룹마다 Header/Footer Row 가 삽입되어 화면 표시 인덱스가 DataList 인덱스와 달라집니다.\n[표시 레이아웃] 0:[부산 Header] / 1:부산 김철수(DataList idx0) / 2:부산 박민수(DataList idx1) / 3:[부산 Footer] / 4:[서울 Header] / 5:서울 홍길동(DataList idx2) / 6:서울 이영희(DataList idx3) / 7:[서울 Footer]\n[절차] par_rowIndex(표시 인덱스) 선택 후 getRealRowIndex 버튼을 클릭합니다.\n[확인] 데이터 Row(1,2,5,6) 선택 시 DataList 인덱스(Number) 반환, Header/Footer(0,3,4,7) 선택 시 Group 정보(Object, type=header/footer) 반환, 음수/범위초과(-1,99) 및 [생략] 옵션은 undefined 반환."', '', 'label1');

    // === 바인딩 DataList(dlt_bind) : region 별로 흩어진 데이터(그룹화 전 순서) ===
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="region" name="region" dataType="text"></w2:column>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="amount" name="amount" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // DataList 원본 순서 : 그룹 정렬 순서(region 오름차순)와 동일하게 넣어 원본 인덱스 == 물리 인덱스 보장
    //  idx0 부산/김철수, idx1 부산/박민수, idx2 서울/홍길동, idx3 서울/이영희
    let jsonData = [
        { "region": "부산", "name": "김철수", "amount": 200 },
        { "region": "부산", "name": "박민수", "amount": 400 },
        { "region": "서울", "name": "홍길동", "amount": 100 },
        { "region": "서울", "name": "이영희", "amount": 300 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // target 그리드 생성 (region / name / amount)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" rowNumVisible="true" id="" style="width:600px;height:400px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getRealRowIndex (GroupBy) 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol_region" value="지역(region)"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" id="hcol_name" value="이름"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol_amount" value="금액"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" dataType="text" id="region" dataList="region"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" dataType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" displayFormat="#,###" id="amount" dataList="amount"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // region(컬럼 인덱스 0) 기준 GroupBy 적용 → 표시 순서 != DataList 순서, 그룹별 Header/Footer 생성
    let colCnt = target1.getColCnt() + target1.defaultColCnt;
    target1.groupby({
        sortIndex: [0],
        sortOrder: [1],
        rowNumHeader: { colSpan: colCnt, inputType: "expression", expression: " toggle() + depthStr() + ' [ ' + count() + ' 건 ] ' ", align: "left" },
        footerVisible: true,
        rowNumFooter: { colSpan: colCnt, inputType: "expression", expression: " '소계 ' + sum('amount') ", align: "right" }
    });
}



// [getRealRowIndex 버튼] : par_rowIndex(표시 기준 인덱스) 선택값으로 getRealRowIndex 호출
//  - 데이터 Row      : Number 반환 → DataList 기준 인덱스 출력
//  - Header/Footer Row : Object 반환 → type 등 Group 정보 속성 개별 출력
//  - 유효하지 않은 값(음수/범위초과) / "생략" 옵션 : undefined 반환
scwin.btn_getRealRowIndex_onclick = function () {
    let b = wf_body_bottom.getObj("scwin");
    let raw = par_rowIndex.getValue();

    // "생략" 옵션 : rowIndex 파라미터를 생략하여 인자 없이 호출 → undefined
    if (raw === "omit") {
        let result = target1.getRealRowIndex();
        b.setReturnValue("getRealRowIndex() (파라미터 생략) 반환 : " + result + " (유효하지 않은 파라미터)");
        return;
    }

    let rowIndex = parseInt(raw, 10);
    let result = target1.getRealRowIndex(rowIndex);

    if (typeof result === "object" && result !== null) {
        // GroupBy Header/Footer Row → Group 정보 Object
        b.setReturnValue("getRealRowIndex(" + rowIndex + ") 반환 : Object (Group 정보)");
        b.setReturnValue("type : " + result.type);
        b.setReturnValue("groupId : " + result.groupId);
        b.setReturnValue("depth : " + result.depth);
        b.setReturnValue("index : " + result.index);
        b.setReturnValue("전체 키 : " + Object.keys(result).join(", "));
    } else if (typeof result === "number") {
        // 데이터 Row → DataList 기준 인덱스(Number)
        b.setReturnValue("getRealRowIndex(" + rowIndex + ") 반환 : " + result);
    } else {
        b.setReturnValue("getRealRowIndex(" + rowIndex + ") 반환 : " + result + " (유효하지 않은 파라미터)");
    }
};
